// Trivia: one question with four options, one try per person, and the first to get it right gets paid. Used by
// .trivia (on demand) and by lightning trivia (which fires on its own, see trivia-relampago.js). The questions are
// generated by the AI, rationed per group (TRIVIA.IA_*); past that, or if it doesn't answer, they come from the bank.
// You reply with the letter, quoting the question or loose in the chat, and the option's text works too.
import { preguntarIA } from "./ia.js";
import { vuelveGeminiEn } from "./gemini.js";
import { elegirAlAzar, mezclar } from "./azar.js";
import { BANCO } from "./trivia-banco.js";
import { marcarMensajeDeJuego } from "./mensajes-de-juego.js";
import { configuracion } from "./configuracion.js";

export const TRIVIA = {
  SEGUNDOS: 30, // how long a .trivia round lasts
  RECIENTES: 25, // questions remembered per group so they aren't repeated
  // How long a round may take to set up before its hold lapses. Longer than the worst setup: every AI model timing out
  // (Gemini 3 × 15 s, then the backup providers' 11 × 20 s, lib/gemini.js and lib/respaldo-ia.js) plus the question's
  // turn in the queue (no ceiling since lib/ritmo.js sends a long queue late instead of all at once, but in practice
  // a few seconds). It's only a safety net for a setup that never ends: one that fails releases the hold
  // itself. At 60 s a slow setup lost its hold halfway, and another round could start in the meantime.
  RESERVA_MS: 5 * 60 * 1000,
  // The AI's questions are rationed per group: each one is a request to the same models Claudia chats with, and
  // twenty .trivia in a row ran out the per-minute quota and paused all three, for the chat too. Past these, the
  // question comes from the bank.
  IA_CADA_MS: 60 * 1000, // at most one AI question a minute
  IA_POR_DIA: 25,
  // The AI's fact about the answer, told when the round closes: one short sentence. A longer one is left out rather
  // than cut, and the question goes without it.
  DATO_MAX: 220,
};
const LETRAS = ["a", "b", "c", "d"];
// The AI's topics, one at random for each question. Exported for the tests.
export const TEMAS = ["geografía", "historia", "ciencia", "matemática", "física", "cine y series", "música", "deportes", "Uruguay", "comida", "tecnología", "animales", "literatura", "cultura pop"];
// The ones that can turn into a sum: answered from a phone in a .trivia's time, so a concept, a unit, a formula or a
// short sum, of what's taught in high school. And short for the AI too: a sum it gets wrong makes the "right" answer
// wrong.
const TEMAS_DE_CUENTAS = new Set(["matemática", "física"]);
const DE_CABEZA = `Tiene que poder responderse de cabeza en menos de ${TRIVIA.SEGUNDOS} segundos, sin papel ni calculadora, con lo que se ve en secundaria: mejor un concepto, una unidad, una fórmula o una cuenta corta que una cuenta larga.`;
const ESQUEMA = {
  type: "object",
  properties: {
    pregunta: { type: "string" },
    opciones: { type: "array", items: { type: "string" } },
    correcta: { type: "string", enum: ["A", "B", "C", "D"] },
    dato: { type: "string" },
  },
  required: ["pregunta", "opciones", "correcta", "dato"],
};

export const rondasTrivia = new Map(); // chat -> ronda abierta
export const triviaConIa = new Map(); // chat -> { dia, usadas, ultima }
const recientes = new Map(); // chat -> the latest questions asked

export const normalizar = (t) =>
  String(t || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .replace(/[^\p{L}\p{N}]+/gu, " ")
    .trim();

const recordar = (chat, pregunta) => {
  const lista = recientes.get(chat) || [];
  lista.push(pregunta);
  if (lista.length > TRIVIA.RECIENTES) lista.shift();
  recientes.set(chat, lista);
};

// Whether the group's next question may come from the AI, counting it if so (answered or not: it's a request all the
// same). With every Gemini model paused, it wouldn't be Gemini but the backups, slow and what the chat is getting by
// on: the bank, instant, is the better question then.
function tocaIa(chat, ahora) {
  if (!configuracion.geminiApiKey || vuelveGeminiEn(ahora) > 0) return false;
  const dia = new Date(ahora).toDateString();
  const uso = triviaConIa.get(chat);
  const usadas = uso?.dia === dia ? uso.usadas : 0;
  if (usadas >= TRIVIA.IA_POR_DIA || ahora - (uso?.ultima || 0) < TRIVIA.IA_CADA_MS) return false;
  triviaConIa.set(chat, { dia, usadas: usadas + 1, ultima: ahora });
  return true;
}

// A fresh question for the group: from the AI when it's its turn (tocaIa) and it answers properly, otherwise from the
// bank, and in both cases without repeating the latest ones.
export async function generarPregunta(chat) {
  const hechas = recientes.get(chat) || [];
  if (tocaIa(chat, Date.now())) {
    const tema = elegirAlAzar(TEMAS);
    // A fact nobody disputes: it asked which river is the longest in the world, which is the Nile or the Amazon
    // depending on how it's measured, and whoever answered the other one lost.
    const r = await preguntarIA(`Escribí UNA pregunta de trivia de ${tema}, de dificultad media, con exactamente 4 opciones cortas y una sola correcta.${TEMAS_DE_CUENTAS.has(tema) ? ` ${DE_CABEZA}` : ""} La respuesta tiene que ser un hecho establecido y sin discusión: nada que dependa de cómo se mida o de qué fuente se mire (como cuál es el río más largo del mundo, que según el criterio es el Nilo o el Amazonas), ni opiniones, ni récords que cambian con el tiempo. Respondé solo con los campos "pregunta", "opciones" (los 4 textos, sin letra adelante), "correcta" (A, B, C o D) y "dato": una sola oración corta que sume algo cierto e interesante sobre la respuesta, sin repetir la pregunta; también tiene que ser un hecho establecido.`, { schema: ESQUEMA }).catch(() => ({ ok: false }));
    if (r.ok) {
      try {
        const d = JSON.parse(r.texto);
        const opciones = Array.isArray(d.opciones) ? d.opciones.map((o) => String(o).trim()) : [];
        const correcta = /^[ABCD]$/.test(d.correcta) ? opciones[LETRAS.indexOf(d.correcta.toLowerCase())] : undefined;
        // Four different options: two that read the same ("Tokio" and "tokio") took an answer by its text to the first
        // of them (parsearRespuesta), right or not.
        const distintas = opciones.length === 4 && opciones.every(Boolean) && new Set(opciones.map(normalizar)).size === 4;
        if (d.pregunta && distintas && correcta !== undefined && !hechas.includes(String(d.pregunta).trim())) {
          // Shuffled, the right one wherever it lands: they came in the order the AI wrote them, and if it tends to put
          // the right one in the same place, the letter gives it away. The bank already spreads them evenly.
          const mezcladas = mezclar(opciones);
          // A fact about the answer, for when the round closes (conDato): people learn playing, and the answer alone
          // says what but not why. The bank's questions have none.
          const dato = typeof d.dato === "string" ? d.dato.trim() : "";
          const conSuDato = dato && dato.length <= TRIVIA.DATO_MAX ? { dato } : {};
          return { pregunta: String(d.pregunta).trim(), opciones: mezcladas, correcta: LETRAS[mezcladas.indexOf(correcta)], ...conSuDato };
        }
      } catch {}
    }
  }
  const candidatas = BANCO.filter((p) => !hechas.includes(p.pregunta));
  return elegirAlAzar(candidatas.length ? candidatas : BANCO);
}

export const rondaDe = (chat) => rondasTrivia.get(chat) || null;

// Holds the chat's turn while the question is generated (the AI takes a while), so two trivias can't open at once.
// Returns the hold, which whoever took it hands to abrirRonda and liberarRonda, or false if there is already a round
// or a hold. The hold releases itself if whoever took it never opens the round.
export function reservarRonda(chat, tipo) {
  if (rondasTrivia.has(chat)) return false;
  const reserva = { tipo, reservada: true, vence: Date.now() + TRIVIA.RESERVA_MS, intentos: new Set(), timeout: null };
  reserva.timeout = setTimeout(() => {
    if (rondasTrivia.get(chat) === reserva) rondasTrivia.delete(chat);
  }, TRIVIA.RESERVA_MS);
  rondasTrivia.set(chat, reserva);
  return reserva;
}
// Releases a hold. Given "reserva", only if it's still that one: a setup whose hold lapsed mustn't release the one
// someone else took afterwards.
export function liberarRonda(chat, reserva = null) {
  const r = rondaDe(chat);
  if (!r?.reservada || (reserva && r !== reserva)) return false;
  clearTimeout(r.timeout);
  rondasTrivia.delete(chat);
  return true;
}
export const segundosRestantes = (ronda) => Math.max(0, Math.ceil((ronda.vence - Date.now()) / 1000));
const textoCorrecta = (p) => `${p.correcta.toUpperCase()}) ${p.opciones[LETRAS.indexOf(p.correcta)]}`;
// The closing's line, with the question's fact after it when it has one (generarPregunta).
const conDato = (texto, p) => (p.dato ? `${texto}\n💡 ${p.dato}` : texto);

export function textoPregunta({ titulo, premio, pregunta, segundos }) {
  const cabecera = premio ? `${titulo} — ${premio} UruCoins para el primero que acierte` : titulo;
  const opciones = pregunta.opciones.map((o, i) => `${LETRAS[i].toUpperCase()}) ${o}`).join("\n");
  return `${cabecera}\n\n${pregunta.pregunta}\n${opciones}\n\n_Respondé con la letra, citando este mensaje o suelta en el chat. ${segundos} segundos y un solo intento por persona._`;
}

// Opens the group's round. alGanar(lid) and alVencer() may return extra text for the closing message (prize, bets).
// Returns the round, or null when the chat's turn belongs to another one.
export function abrirRonda(chat, { tipo, pregunta, mensajeId, segundos, client, alGanar = null, alVencer = null, reserva = null }) {
  // Replies to the question are answers, not messages for Claudia, nor moves of another game.
  marcarMensajeDeJuego(mensajeId, chat, { juego: "trivia" });
  // It takes over its own hold (or, called without one, whichever hold there is), or a free chat. Never a round in
  // play: overwriting one killed it without a word, and its answers went nowhere. That happened when a slow setup lost
  // its hold and another trivia opened in the meantime.
  const actual = rondaDe(chat);
  if (actual && actual !== reserva && !(reserva === null && actual.reservada)) {
    console.error(`[trivia] no abro la ronda (${tipo}) en ${chat}: el turno ya es de otra`);
    return null;
  }
  liberarRonda(chat, reserva); // the hold, if there was one, is taken over by this round
  const ronda = { tipo, pregunta, mensajeId, intentos: new Set(), vence: Date.now() + segundos * 1000, alGanar, alVencer, timeout: null };
  ronda.timeout = setTimeout(() => {
    if (rondasTrivia.get(chat) !== ronda) return;
    rondasTrivia.delete(chat);
    client.sendMessage(chat, { text: pegar(conDato(`⏳ Nadie acertó. Era *${textoCorrecta(pregunta)}*.`, pregunta), alVencer?.()) }).catch(console.error);
  }, segundos * 1000);
  rondasTrivia.set(chat, ronda);
  recordar(chat, pregunta.pregunta);
  return ronda;
}

const pegar = (base, extra) => (extra ? `${base}${extra.startsWith("\n") ? "" : "\n"}${extra}` : base);

// Which letter they meant, or null if it isn't an answer:
//   - the letter alone, with punctuation, and with "la" or "opción" ahead if they come: "c", "C)", "(c)", "c.", "la c",
//     "Opción C"; with one of those ahead, whatever follows ("la c, porque sí");
//   - the letter marked as an option, and some text after it: "c) Tokio", "C) porque sí", "c. tokio", "c, claudia"
//     (an answer that names her is still an answer);
//   - the letter and exactly that option's text ("c tokio"), or an option's text alone ("tokio").
// A letter followed by just any words isn't: with a round open, "a ver claudia", "a qué hora es" or "d nada" spent the
// person's one attempt, and Claudia, named, said nothing.
export function parsearRespuesta(texto, opciones) {
  const t = normalizar(texto);
  if (!t) return null;
  // The marks of an option (")", ".", ":", ",", "-") are what normalizar takes away: read on the text as it came.
  const crudo = String(texto || "").trim().toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "");
  const marcada = crudo.match(/^(?:la |opcion |\()?([abcd])\s*[).:,-]/);
  if (marcada) return marcada[1];
  const letra = t.match(/^(la |opcion )?([abcd])(?: (.+))?$/);
  if (letra && (!letra[3] || letra[1] || normalizar(opciones[LETRAS.indexOf(letra[2])]) === letra[3])) return letra[2];
  const i = opciones.findIndex((o) => normalizar(o) === t);
  return i >= 0 ? LETRAS[i] : null;
}

// Called on every message. Returns { reaccion, texto?, mentions? } if the message was an answer to the chat's open
// round, and null if there was no round or the message wasn't an answer.
export function responderTrivia(m) {
  const ronda = rondaDe(m.chat);
  if (!ronda || ronda.reservada) return null;
  if (m.quoted?.id && m.quoted.id !== ronda.mensajeId) return null; // it quotes something else, not the trivia
  const letra = parsearRespuesta(m.text, ronda.pregunta.opciones);
  if (!letra) return null;
  if (ronda.intentos.has(m.sender)) return { reaccion: "🙅" };
  ronda.intentos.add(m.sender);
  if (letra !== ronda.pregunta.correcta) return { reaccion: "❌" };
  clearTimeout(ronda.timeout);
  rondasTrivia.delete(m.chat);
  const texto = pegar(conDato(`✅ ¡Acertó @${m.sender.split("@")[0]}! Era *${textoCorrecta(ronda.pregunta)}*.`, ronda.pregunta), ronda.alGanar?.(m.sender));
  return { reaccion: "✅", texto, mentions: [m.sender] };
}

// For the tests and for .trivia when the game is cut short from outside.
export function cerrarRonda(chat) {
  const ronda = rondaDe(chat);
  if (!ronda) return false;
  clearTimeout(ronda.timeout);
  rondasTrivia.delete(chat);
  return true;
}
